const refinedCopy={
es:{craft:'La música. El oficio. La búsqueda.',craftText:'Heredé de mi abuelo, artesano del metal, y de mi padre, artesano de la madera, el placer de transformar la materia. La guitarra reunió esas raíces con mi pasión por la música. Hoy construyo en Francia, siguiendo la tradición española y una búsqueda sonora en constante evolución.',bio:'Conocer mi recorrido',historyTitle:'Raíces argentinas. Oficio en Francia.',historyShort:'Una vida entre la música y la madera, la enseñanza y la investigación. Descubre los encuentros y las historias que acompañan mis instrumentos.',ecoLabel:'ECO · MADERAS ARGENTINAS',ecoTitle:'Cada madera, una posibilidad.',ecoText:'Explorar otras maderas también es explorar otras voces. ECO reúne mis raíces argentinas, el cuidado de los materiales y la búsqueda de riqueza sonora.',ecoLink:'Descubrir ECO',visit:'La próxima guitarra se descubre tocándola.',visitText:'Conversemos sobre el sonido que buscas y la posibilidad de probar los instrumentos del taller.',visitButton:'Conversar sobre una prueba',more:'La búsqueda detrás del instrumento',customTitle:'Del diálogo al instrumento.',steps:[['Escucharte','Tu manera de tocar, tus preferencias y el sonido que buscas.'],['Definir juntos','Exploramos las posibilidades de diseño, materiales y comodidad.'],['Concretar el proyecto','Acordamos las características, el presupuesto y los plazos antes de empezar.']],bioTitle:'Entre la música y la madera.',bioBody:'Mi camino comenzó con la guitarra clásica y las músicas de Argentina. En 2008 me trasladé a París, donde me formé en la luthería tradicional española con Liberto Planas; más tarde continué mi aprendizaje con Walter Verreydt en Bélgica. En 2013 asumí la enseñanza de luthería en Paris Ateliers. El oficio, la música y la transmisión siguen siendo parte de una misma búsqueda.',projectLink:'La voz de las maderas · conocer el proyecto',modelDetails:{'T-1':'Una construcción artesanal de estética sencilla. Su disponibilidad se conversa directamente con el taller.','T-2':'El equilibrio entre sonido, comodidad y sobriedad guía este modelo. Una guitarra para quienes disfrutan tanto de la respuesta del instrumento como de la naturalidad al tocar.','T-3':'La proyección, la riqueza de armónicos y la duración del sonido orientan su desarrollo, sin dejar atrás la calidez y la dulzura tradicionales. Una investigación que permanece abierta.',ECO:'El proyecto nace de la exploración de maderas alternativas argentinas y del aprovechamiento cuidadoso de los materiales. Cada combinación abre una nueva búsqueda de equilibrio y expresión.',special:'Guitarrón argentino, guitarra bajo y requinto responden a distintas funciones musicales. Conversemos sobre el instrumento y el registro que buscas.',custom:'Las posibilidades se estudian para cada encargo. La elección de maderas, las dimensiones y los detalles se definen según el proyecto y su viabilidad.'}},
fr:{craft:'La musique. Le métier. La recherche.',craftText:'De mon grand-père, artisan du métal, et de mon père, artisan du bois, j’ai hérité du plaisir de transformer la matière. La guitare a réuni ces racines et ma passion pour la musique. Aujourd’hui, je construis en France, dans la tradition espagnole et avec une recherche sonore en constante évolution.',bio:'Découvrir mon parcours',historyTitle:'Des racines argentines. Un savoir-faire en France.',historyShort:'Une vie entre la musique et le bois, l’enseignement et la recherche. Découvrez les rencontres et les histoires qui accompagnent mes instruments.',ecoLabel:'ECO · BOIS ARGENTINS',ecoTitle:'Chaque bois, une possibilité.',ecoText:'Explorer d’autres bois, c’est aussi explorer d’autres voix. ECO réunit mes racines argentines, le soin porté aux matériaux et la recherche de richesse sonore.',ecoLink:'Découvrir ECO',visit:'Une guitare se découvre en la jouant.',visitText:'Échangeons sur le son que vous recherchez et la possibilité d’essayer les instruments de l’atelier.',visitButton:'Parlons d’un essai',more:'La recherche derrière l’instrument',customTitle:'Du dialogue à l’instrument.',steps:[['Vous écouter','Votre façon de jouer, vos préférences et le son que vous recherchez.'],['Définir ensemble','Nous explorons les possibilités de conception, de matériaux et de confort.'],['Préciser le projet','Nous convenons des caractéristiques, du devis et des délais avant de commencer.']],bioTitle:'Entre la musique et le bois.',bioBody:'Mon parcours a commencé avec la guitare classique et les musiques d’Argentine. En 2008, je me suis installé à Paris, où je me suis formé à la lutherie traditionnelle espagnole auprès de Liberto Planas ; j’ai ensuite poursuivi mon apprentissage avec Walter Verreydt en Belgique. En 2013, j’ai repris l’enseignement de la lutherie à Paris Ateliers. Le métier, la musique et la transmission restent au cœur d’une même recherche.',projectLink:'La voix des bois · découvrir le projet',modelDetails:{'T-1':'Une fabrication artisanale à l’esthétique simple. Sa disponibilité est à discuter directement avec l’atelier.','T-2':'L’équilibre entre son, confort et sobriété guide ce modèle. Une guitare pour ceux qui apprécient autant la réponse de l’instrument que le naturel du jeu.','T-3':'La projection, la richesse harmonique et la durée du son orientent son développement, sans renoncer à la chaleur et à la douceur traditionnelles. Une recherche qui reste ouverte.',ECO:'Le projet naît de l’exploration de bois alternatifs argentins et d’une utilisation attentive des matériaux. Chaque association ouvre une nouvelle recherche d’équilibre et d’expression.',special:'Le guitarrón argentin, la guitare basse et le requinto répondent à des rôles musicaux différents. Échangeons sur l’instrument et le registre que vous recherchez.',custom:'Les possibilités sont étudiées pour chaque commande. Le choix des bois, les dimensions et les détails sont définis selon le projet et sa faisabilité.'}},
en:{craft:'Music. Craft. Exploration.',craftText:'From my grandfather, a metalworker, and my father, a woodworker, I inherited the pleasure of shaping materials. Guitar making brought those roots together with my love of music. Today I build in France, drawing on the Spanish tradition and an ever-evolving exploration of sound.',bio:'Discover my story',historyTitle:'Argentine roots. A craft practised in France.',historyShort:'A life shaped by music and wood, teaching and exploration. Discover the encounters and stories behind my instruments.',ecoLabel:'ECO · ARGENTINE WOODS',ecoTitle:'Every wood, a possibility.',ecoText:'Exploring different woods means exploring different voices. ECO brings together my Argentine roots, care for materials and the search for tonal richness.',ecoLink:'Discover ECO',visit:'A guitar is discovered by playing it.',visitText:'Let’s talk about the sound you seek and the possibility of trying the workshop’s instruments.',visitButton:'Talk about trying a guitar',more:'The exploration behind the instrument',customTitle:'From conversation to instrument.',steps:[['Listening to you','Your playing, your preferences and the sound you seek.'],['Defining it together','We explore possibilities for design, materials and playing comfort.'],['Shaping the project','We agree on specifications, a quotation and timing before work begins.']],bioTitle:'Between music and wood.',bioBody:'My journey began with classical guitar and the music of Argentina. In 2008 I moved to Paris, where I trained in traditional Spanish guitar making with Liberto Planas; I later continued my studies with Walter Verreydt in Belgium. In 2013 I took over teaching guitar making at Paris Ateliers. Craft, music and passing on knowledge remain part of the same exploration.',projectLink:'The voice of the woods · explore the project',modelDetails:{'T-1':'Handcrafted with simple aesthetics. Availability can be discussed directly with the workshop.','T-2':'A balance of sound, comfort and restraint guides this model. A guitar for those who value both the instrument’s response and a natural playing experience.','T-3':'Projection, harmonic richness and sustain guide its development, while preserving traditional warmth and sweetness. An exploration that remains open.',ECO:'The project explores alternative Argentine woods and thoughtful use of materials. Each combination opens a new search for balance and expression.',special:'Argentine guitarrón, bass guitar and requinto serve different musical roles. Let’s discuss the instrument and range you are looking for.',custom:'Possibilities are explored for each commission. Woods, dimensions and details are defined according to the project and its feasibility.'}}
};
const beforeRefinedHome=renderHome;
renderHome=function(){beforeRefinedHome();const c=refinedCopy[lang];
// Keep the established recording section; add no new audio surfaces.
document.querySelector('.manifesto')?.remove();document.querySelector('.home-project')?.remove();
const history=document.querySelector('.history-teaser');history.innerHTML=`<div><p class="eyebrow">VICTOR IERMITO</p><h2>${c.historyTitle}</h2><p>${c.historyShort}</p><a class="text-link" href="#/press">${c.bio} ↗</a></div>`;
const atelier=document.querySelector('.atelier');atelier.querySelector('h2').textContent=c.craft;atelier.querySelector('p:not(.eyebrow)').textContent=c.craftText;const bio=atelier.querySelector('.text-link');bio.href='#/press';bio.textContent=c.bio+' ↗';
atelier.insertAdjacentHTML('afterend',`<section class="eco-editorial section"><div><p class="eyebrow">${c.ecoLabel}</p><h2>${c.ecoTitle}</h2><p>${c.ecoText}</p><a class="text-link" href="#/guitars/ECO">${c.ecoLink} ↗</a></div><a href="#/guitars/ECO" aria-label="${c.ecoLink}"><img src="assets/real/real-rosette.jpg" alt="Victor Iermito · ${tr('details')}" loading="lazy"></a></section>`);
const contact=document.querySelector('.contact');contact.querySelector('h2').textContent=c.visit;contact.querySelector('h2').insertAdjacentHTML('afterend',`<p class="visit-text">${c.visitText}</p>`);contact.querySelector('.button').innerHTML=c.visitButton+' ↗';};
const beforeRefinedModel=renderModel;
renderModel=function(k){beforeRefinedModel(k);if(!refinedCopy[lang].modelDetails[k])return;const c=refinedCopy[lang];const copy=document.querySelector('.detail-copy');const link=copy.querySelector('.custom-button');link.insertAdjacentHTML('beforebegin',`<details class="making-notes"><summary>${c.more}</summary><p>${c.modelDetails[k]}</p></details>`);if(k==='ECO')copy.insertAdjacentHTML('beforeend',`<a class="quiet-link" href="#/projects">${c.projectLink} ↗</a>`);if(k==='custom')document.querySelector('.detail-layout').insertAdjacentHTML('afterend',`<section class="commission-steps"><p class="eyebrow">${modelName(k)}</p><h2>${c.customTitle}</h2><div>${c.steps.map(([t,p],i)=>`<article><span>0${i+1}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>`);};
const beforeRefinedPress=renderPress;
renderPress=function(){beforeRefinedPress();const c=refinedCopy[lang];document.querySelector('.history-lead').insertAdjacentHTML('afterend',`<article class="maker-biography"><h2>${c.bioTitle}</h2><p>${c.bioBody}</p></article>`);};
